function [w] = fsw_rate_rad(deg_s)
%FSW_RATE_RAD  A rate [rad/s] from the degrees per second a scenario states it in (the detumble's exit rate, detumble_exit).
%   deg_s: real[1] (passed a plain number)
%   returns w: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    w = 0;
    w = ((deg_s * pi) / 180);
end
